SYNC=r'''async()=>{const g=__bulkUi.editor.graph;await document.fonts.ready;g.refresh();g.view.validate();await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));g.view.validate();const b=g.getGraphBounds();return {bounds:{x:b.x,y:b.y,width:b.width,height:b.height},currentStyle:g.currentStyle,background:g.background,model:mxUtils.getXml(__bulkUi.editor.getGraphXml()),cells:Object.values(g.model.cells).map(c=>({id:c.id,parent:c.parent?.id,source:c.source?.id,target:c.target?.id,vertex:!!c.vertex,edge:!!c.edge,geometry:c.geometry?{x:c.geometry.x,y:c.geometry.y,width:c.geometry.width,height:c.geometry.height,relative:c.geometry.relative,points:c.geometry.points}:null,style:c.style})).sort((a,b)=>a.id.localeCompare(b.id))};}'''
