  state=lambda s:sha(json.dumps(s['cells'],sort_keys=True).encode());proof={'policy':POLICY,'source_XML_sha256':sha(xml.encode() if isinstance(xml,str) else xml),'source_decoded_model_sha256':sha(model.encode()),'options_from_settled_source_graph_only':options,'source_initial_state':{k:v for k,v in initial.items() if k not in {'model','cells'}},'source_geometry_topology_style_inventory_sha256':state(initial),'restored_geometry_topology_style_inventory_sha256':state(restored),'normalized_model_exact_restore':initial['model']==restored['model'],'mutation_normalized_model_changed':mutated['model']!=initial['model'],'mutation_actual_RGBA_changed':pixels(mp)!=pixels(png),'restored_actual_RGBA_exact':pixels(rp)==pixels(png),'restored_PNG_bytes_exact':rp==png,'restored_SVG_namespace_canonical_exact':canonical(svg)==canonical(rsvg),'resource_closure':closure,'font_observations':fonts,'source_official_PNG_sha256':sha(png),'source_official_SVG_sha256':sha(svg.encode()),'init_move_restore_uniform_refresh_validate_fonts_ready_two_RAF':True,'source_and_export_pages_brought_to_front_before_RAF':True,'source_Editor_WAR_32_6_1':True,'historical_author_OS_fonts_exact':False,'standalone_font_portability_certified':False,'native_code_modified':False,'new_PDF_import_calls':0,'new_normal_calls':0,'new_model_calls':0,'stage_seconds':{'source_export_and_actual_fonts':font_seconds,'native_edit_restore':time.monotonic()-tick-font_seconds},'seconds':time.monotonic()-tick}
  proof['ok']=all(proof[k] for k in ['normalized_model_exact_restore','mutation_normalized_model_changed','mutation_actual_RGBA_changed','restored_actual_RGBA_exact','restored_PNG_bytes_exact','restored_SVG_namespace_canonical_exact']) and state(initial)==state(restored) and not self.r.blocked and not self.r.missing and not closure['failed'];proof['blocked']=self.r.blocked[:5];proof['missing']=self.r.missing[:5];(folder/'synced_replay_proof.json').write_text(json.dumps(proof,ensure_ascii=False,indent=2)+'\n');return proof
